const guides=[
 {title:"DOE Genesis Mission official overview",summary:"Primary source for DOE mission objectives and scientific-platform priorities.",url:"https://genesis.energy.gov/",date:"",source:"DOE",category:"National challenges",tier:"Official",kind:"guide"},
 {title:"DOE Genesis Mission program hub",summary:"Official program information, initiatives and announcements.",url:"https://www.energy.gov/undersecretaryforscience/genesis-mission/genesis-mission",date:"",source:"DOE",category:"National challenges",tier:"Official",kind:"guide"},
 {title:"DOE Genesis news archive",summary:"Official collection of DOE Genesis Mission news.",url:"https://www.energy.gov/undersecretaryforscience/genesis-mission/listings/genesis-mission-news",date:"",source:"DOE",category:"Partnerships",tier:"Official",kind:"guide"},
 {title:"DOE Office of Science news",summary:"Broader Office of Science updates that may intersect with Genesis.",url:"https://www.energy.gov/science/listings/office-science-news",date:"",source:"DOE",category:"AI models",tier:"Related",kind:"guide"},
 {title:"Oak Ridge Genesis projects",summary:"ORNL descriptions of Genesis projects and research areas.",url:"https://www.ornl.gov/genesis-mission-ai-driven-projects/",date:"",source:"ORNL",category:"AI models",tier:"Related",kind:"guide"},
 {title:"Argonne Leadership Computing Facility: Genesis",summary:"Facility perspective on Genesis scientific computing.",url:"https://www.alcf.anl.gov/genesis-mission",date:"",source:"Argonne",category:"Infrastructure",tier:"Related",kind:"guide"},
 {title:"Berkeley Lab Genesis Mission",summary:"Laboratory news and work on AI-enabled science.",url:"https://www.lbl.gov/genesis-mission/",date:"",source:"Berkeley Lab",category:"Partnerships",tier:"Related",kind:"guide"},
 {title:"Savannah River National Lab Genesis",summary:"Scientific data and models for mission applications.",url:"https://www.srnl.gov/srnl-genesis-mission/",date:"",source:"SRNL",category:"Data",tier:"Related",kind:"guide"}
];
const projects=[
 {title:"GridFM 2.0",summary:"Brookhaven-led effort using artificial intelligence to accelerate electric-grid planning; linked to a DOE $11.5 million project announcement.",url:"https://www.energy.gov/oe/articles/does-office-electricity-announces-115m-genesis-mission-project-meet-growing-electricity",date:"2026-09-01",source:"Brookhaven / DOE",category:"Infrastructure",tier:"Official",kind:"project",organization:"Brookhaven National Laboratory"},
 {title:"AI4HPC",summary:"Argonne-led AI-assisted scientific software development and optimization, cited in DOE's October 2026 award announcement.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"Argonne / DOE",category:"AI models",tier:"Official",kind:"project",organization:"Argonne National Laboratory"},
 {title:"MOAT-Core",summary:"Berkeley-led shared AI platform supporting accelerator science.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"Berkeley / DOE",category:"AI models",tier:"Official",kind:"project",organization:"Berkeley Lab"},
 {title:"MAESTRO",summary:"AI reasoning and optimization for geothermal-reservoir research; UC Irvine-led.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"UC Irvine / DOE",category:"National challenges",tier:"Official",kind:"project",organization:"University of California, Irvine"},
 {title:"AXESS",summary:"AI-enabled design of microchips for extreme environments; Fermilab-led.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"Fermilab / DOE",category:"National challenges",tier:"Official",kind:"project",organization:"Fermilab"},
 {title:"AI-assisted quantum magnet design",summary:"Oak Ridge-led research into quantum materials with desired magnetic properties.",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",date:"2026-10-08",source:"ORNL / DOE",category:"AI models",tier:"Official",kind:"project",organization:"Oak Ridge National Laboratory"}
];
const announcements=[
 {title:"DOE announces additional Genesis Mission Phase II awards",summary:"DOE announced 12 new Phase II awards totaling $159 million and described a first-year portfolio of 297 projects.",date:"2026-10-08",url:"https://www.energy.gov/articles/energy-department-announces-new-genesis-mission-awards-advance-super-intelligence-science",source:"DOE",category:"National challenges",tier:"Official",kind:"news"},
 {title:"ORNL selected for six Phase II Genesis awards",summary:"Laboratory awards span materials, microelectronics, quantum computing, accelerator software and fusion.",date:"2026-10-08",url:"https://www.ornl.gov/news/ornl-selected-for-six-phase-ii-genesis-mission-awards/",source:"ORNL",category:"AI models",tier:"Related",kind:"news"}
];
const labs=[["DOE","https://www.energy.gov/"],["Genesis Mission","https://genesis.energy.gov/"],["Oak Ridge","https://www.ornl.gov/"],["Argonne","https://www.anl.gov/"],["Brookhaven","https://www.bnl.gov/"],["Berkeley Lab","https://www.lbl.gov/"],["Los Alamos","https://www.lanl.gov/"],["Pacific Northwest","https://www.pnnl.gov/"],["Sandia","https://www.sandia.gov/"],["Idaho National Lab","https://inl.gov/"],["Fermilab","https://www.fnal.gov/"],["SLAC","https://www6.slac.stanford.edu/"]];
const categories=["All","Data","Infrastructure","AI models","National challenges","Partnerships"];
let live=[],checkedAt="",liveStatus=[],section="All",mode="All",category="All",limit=12,selectedTier="All";
const escapeHTML=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const safeUrl=url=>{try{const u=new URL(url);return u.protocol==="https:"?u.href:"#"}catch{return"#"}};
const dateText=s=>s&&Number.isFinite(Date.parse(s))?new Date(s).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}):"SOURCE GUIDE";
function allRecords(){const seen=new Set();return [...live,...announcements,...projects,...guides].filter(d=>{const key=d.kind+"|"+d.title.toLowerCase().replace(/[^a-z0-9]/g,"").slice(0,70);if(seen.has(key))return false;seen.add(key);return true})}
function filtered(){const q=$("search").value.toLowerCase().trim();const tokens=q.split(/\s+/).filter(Boolean);return allRecords().filter(d=>{if(mode==="News"&&d.kind!=="news"&&d.kind!=="discovery")return false;if(mode==="Projects"&&d.kind!=="project")return false;if(mode==="Guides"&&d.kind!=="guide")return false;if(section==="News"&&d.kind!=="news"&&d.kind!=="discovery")return false;if(section==="Archive"&&d.kind==="guide")return false;if(section==="Sources"&&d.kind!=="guide")return false;if(section==="Projects"&&d.kind!=="project")return false;if(section==="Labs"&&!/lab|ornl|argonne|brookhaven|fermilab|sandia|national/i.test((d.source||"")+" "+d.title+" "+(d.organization||"")))return false;if(["Data","Infrastructure","AI models","National challenges","Partnerships"].includes(section)&&d.category!==section)return false;if(category!=="All"&&d.category!==category)return false;if(selectedTier!=="All"&&d.tier!==selectedTier)return false;const hay=[d.title,d.summary,d.source,d.organization,d.category,d.tier].join(" ").toLowerCase();return tokens.every(t=>hay.includes(t))}).sort((a,b)=>{const sort=$("sort").value;if(sort==="az")return a.title.localeCompare(b.title);const cmp=(b.date||"").localeCompare(a.date||"");return sort==="old"?-cmp:cmp})}
function showPreview(d){$("previewHint").classList.add("hidden");$("preview").classList.remove("hidden");$("preview").innerHTML='<button class="close-preview" id="clearPreview">✕</button><span class="pill">'+escapeHTML(d.tier)+'</span><span class="pill">'+escapeHTML(d.kind)+'</span><h3>'+escapeHTML(d.title)+'</h3><p>'+escapeHTML(d.summary)+'</p><p class="subtle">Source: '+escapeHTML(d.source)+' · '+escapeHTML(dateText(d.date))+' · '+escapeHTML(d.category)+'</p>'+(d.kind==="discovery"?'<p class="subtle">Automated discovery; verify the original announcement and date before citing.</p>':'')+'<a class="external" href="'+safeUrl(d.url)+'" target="_blank" rel="noopener noreferrer">Open source ↗</a>';$("clearPreview").onclick=()=>{$("preview").classList.add("hidden");$("previewHint").classList.remove("hidden")}}
function render(){const list=filtered();$("recordCount").textContent=String(list.length);$("projectCount").textContent=String(projects.length);$("sourceCount").textContent=String(liveStatus.filter(x=>x.ok).length)+"/3";$("count").textContent=list.length+" matching records";
 $("rows").innerHTML=list.slice(0,limit).map((d,i)=>'<article class="news-item"><div class="news-thumb '+(d.kind==="project"?"project":"")+'"><i data-lucide="'+(d.kind==="project"?"layers":d.category==="Infrastructure"?"server":d.category==="AI models"?"brain-circuit":d.category==="Data"?"database":"atom")+'"></i></div><div class="news-main"><div class="news-kicker"><span>'+escapeHTML(d.tier.toUpperCase())+'</span><span class="source-org">'+escapeHTML(d.source)+'</span><span class="news-date">'+escapeHTML(dateText(d.date))+'</span></div><h3><button data-record="'+i+'">'+escapeHTML(d.title)+'</button></h3><p>'+escapeHTML(d.summary)+'</p><a class="source-link" href="'+safeUrl(d.url)+'" target="_blank" rel="noopener noreferrer">Original source ↗</a></div></article>').join("")||'<div class="empty">No matching items. Try a broader search.</div>';
 document.querySelectorAll("[data-record]").forEach(b=>b.onclick=()=>showPreview(list[+b.dataset.record]));
 $("more").hidden=list.length<=limit;
 document.querySelectorAll("[data-tier]").forEach(b=>{b.classList.toggle("selected",b.dataset.tier===selectedTier);b.setAttribute("aria-pressed",String(b.dataset.tier===selectedTier))});
 document.querySelectorAll("[data-section]").forEach(b=>{b.classList.toggle("active",b.dataset.section===section);b.setAttribute("aria-current",b.dataset.section===section?"page":"false")});
 const iconNames={Data:"database",Infrastructure:"server", "AI models":"cpu","National challenges":"leaf",Partnerships:"handshake"};
 const labels={Data:"Data",Infrastructure:"Infrastructure","AI models":"AI Models","National challenges":"National Challenges",Partnerships:"Public-Private Partnerships"};
 const total=projects.length; const max=Math.max(...categories.slice(1).map(c=>projects.filter(p=>p.category===c).length),1);
 $("trackerBars").innerHTML=categories.slice(1).map(c=>{const n=projects.filter(p=>p.category===c).length;return '<div class="tracker-row"><div class="tracker-label"><i data-lucide="'+iconNames[c]+'"></i>'+labels[c]+'</div><div class="tracker-track"><div class="tracker-fill" style="width:'+(n/max*100)+'%"></div></div><div class="tracker-count">'+n+'</div></div>'}).join("");
 if(window.lucide)window.lucide.createIcons();
}
function setStatus(text,warn=false){$("feedStatus").textContent=text;$("feedStatus").classList.toggle("warn",warn)}
async function fetchLive(force=false){setStatus("Checking latest news-discovery feeds…");$("refresh").disabled=true;try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),14000);let response;try{response=await fetch("/api/news"+(force?"?refresh="+Date.now():""),{signal:controller.signal,cache:force?"reload":"default"})}finally{clearTimeout(timeout)}if(!response.ok)throw new Error("HTTP "+response.status);const data=await response.json();live=Array.isArray(data.items)?data.items.filter(x=>x&&x.title&&safeUrl(x.url)!=="#").map(x=>({...x,kind:"discovery"})):[];liveStatus=Array.isArray(data.sources)?data.sources:[];checkedAt=data.checkedAt||"";const ok=liveStatus.filter(x=>x.ok).length;if(ok){setStatus("Discovery checked "+new Date(checkedAt).toLocaleString()+" · "+live.length+" aggregated headlines · "+ok+" of 3 sources responding. Verify original sources.");$("time").textContent="LATEST CHECK · "+new Date(checkedAt).toLocaleTimeString([], {hour:"numeric",minute:"2-digit"})}else setStatus("Automated feeds unavailable. Showing the curated source archive; these are not live updates.",true)}catch(err){setStatus("Live feed connection unavailable ("+err.message+"). Showing curated records; no automatic updates verified.",true)}finally{$("refresh").disabled=false;render()}}
$("links").innerHTML=labs.map(([name,url])=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(name)+'<span>↗</span></a>').join("");
$("filters").innerHTML=categories.map(c=>'<button class="chip" data-cat="'+escapeHTML(c)+'">'+escapeHTML(c)+'</button>').join("")+'<select id="tier" aria-label="Source classification"><option value="All">All source tiers</option><option value="Official">Official</option><option value="Related">Related</option><option value="Potentially relevant">Potentially relevant</option></select>';
$("spotlights").innerHTML=projects.slice(0,4).map((d,i)=>'<button class="project" data-project="'+i+'"><b>'+escapeHTML(d.title)+'</b><span>'+escapeHTML(d.organization)+'</span></button>').join("");
document.querySelectorAll("[data-project]").forEach(b=>b.onclick=()=>showPreview(projects[+b.dataset.project]));

document.querySelectorAll("[data-section]").forEach(b=>b.onclick=()=>{section=b.dataset.section;mode=section==="News"?"News":section==="Projects"?"Projects":section==="Sources"?"Guides":"All";category=["Data","Infrastructure","AI models","National challenges","Partnerships"].includes(section)?section:"All";limit=12;render()});
document.querySelectorAll("[data-tier]").forEach(b=>b.onclick=()=>{selectedTier=b.dataset.tier;limit=12;render()});
$("sort").onchange=render;$("search").oninput=()=>{limit=12;render()};$("searchBtn").onclick=()=>{$("search").focus();render()};
$("more").onclick=()=>{limit+=12;render()};$("refresh").onclick=()=>fetchLive(true);
$("researchToggle").onclick=()=>{const sub=$("researchSub");const open=sub.hidden;sub.hidden=!open;$("researchToggle").setAttribute("aria-expanded",String(open))};
$("viewProjects").onclick=()=>{document.querySelector('[data-section="Projects"]').click();document.querySelector(".feed").scrollIntoView({behavior:"smooth"})};
$("resources").onclick=()=>{document.querySelector('[data-section="Sources"]').click();document.querySelector(".feed").scrollIntoView({behavior:"smooth"})};
$("askAI").onclick=()=>{$("dialogBody").innerHTML='<h2>Ask Genesis AI</h2><p>The conversational Genesis research assistant is planned for Build 3 and is not operational yet.</p>';$("dialog").showModal()};
$("about").onclick=()=>{$("dialogBody").innerHTML='<h2>About Genesis Intelligence Hub</h2><p>Independent public-source intelligence dashboard following the DOE Genesis Mission. It is not affiliated with or endorsed by the U.S. Department of Energy.</p><p>Office of Synergy is an independent creative brand, not a DOE office.</p><p>Source headlines from automated discovery require verification against original publications. Tracker totals represent the selected records in this site, not the full DOE project portfolio.</p><p>Build 3 conversational research functionality is not yet implemented.</p>';$("dialog").showModal()};
$("close").onclick=()=>$("dialog").close();
function updateMonitor(){const names=["DOE Genesis","Laboratory Genesis","Genesis related"];const display=["DOE Genesis Mission","National Laboratories","Research & Partner News"];const ok=liveStatus.filter(x=>x.ok).length;const state=$("sourceState");state.textContent=ok?ok+" / 3 responding":"Offline / unverified";state.classList.toggle("ok",ok>0);
 $("sourceMonitor").innerHTML=names.map((name,i)=>{const src=liveStatus.find(x=>x.name===name);return '<div class="monitor-row"><i data-lucide="'+(src?.ok?"check-square":"square-x")+'"></i><span>'+display[i]+'</span><small>'+(src?.ok?src.count+" results":"Unavailable")+'</small></div>'}).join("");
 if(checkedAt&&Number.isFinite(Date.parse(checkedAt)))$("headerUpdate").textContent="Last checked: "+new Date(checkedAt).toLocaleString();
 if(window.lucide)window.lucide.createIcons();
}
const originalFetchLive=fetchLive;
fetchLive=async function(force=false){await originalFetchLive(force);updateMonitor()};
render();updateMonitor();fetchLive();
